function livesOnLava(species) {
  return Boolean(species?.lavaSwimmer || species?.lavaWalker);
}
function pluralOf(species) {
  return species.plural ?? `${species.displayName}s`;
}
function baitItems(species) {
  return [species.baitItem, ...species.baitAlso ?? []].filter(Boolean);
}
function speciesForWild(typeId) {
  return Object.values(SPECIES).find((s4) => s4.wildSource === typeId);
}
function speciesForEntity(typeId) {
  return Object.values(SPECIES).find((s4) => s4.entityType === typeId || s4.youngEntityType === typeId);
}
function entityTypeOf(species, juvenile) {
  return juvenile && species.youngEntityType ? species.youngEntityType : species.entityType;
}
function speciesForMob(typeId) {
  return Object.values(SPECIES).find((s4) => s4.mobSource === typeId);
}

