    shade: 1 / 3,
    shadeComfortCap: 45,
    nestDays: 1,
    // cubs stay in the Nest Box their first park day
    bait: ["zoocraft:leafy_ration"],
    // held this close (8 blocks) by someone, a red panda stops what it's doing for them
    interestTicks: 400,
    // how long it heads for something (a tree, the feeder, a Nest Box) before giving up
