    life: { deep: 0, lantern: 6e-3, pickles: 0.035, picklesHigh: 0.01, lichen: 0.05, kelpScale: 34, kelpEdge: 0.25, kelpChance: 0.4, kelpDeep: 0.015, kelp: [5, 22], kelpTop: 56, grass: 0.3, grassDeep: 0.15, tallGrass: 0.35, vein: 0.05, veinMin: 4 }
