        // Friend: he upgrades your bows, while he's at home and up
        signatureCost: 600,
        // TD 6000 Points
        stageCost: 200,
        // each of Upgrade I, II and III (TD 2000 Points)
        u1Damage: 1.1,
        // TD: Upgrade I, damage x1.1
        u2Draw: 0.9,
        // TD: Upgrade II, the draw takes 90% as long
        u2Spread: 0.9,
        // TD: the Scrap Bow's spread 10% tighter instead
        u2Recovery: 0.9,
        // TD: the Ballista winds back 10% sooner instead
        u3Damage: 1.2,
        // TD: Upgrade III, damage x1.2 in all
        heal: 2
