    netheriteToughness: 4,
    // the kinds of harm armor softens (the rest go straight through, for diamond too)
    armorCauses: ["entityAttack", "projectile", "fire", "lava", "contact", "blockExplosion", "entityExplosion", "fireworks", "lightning", "anvil", "fallingBlock", "stalactite", "magma", "thorns", "ramAttack", "maceSmash", "piston", "campfire", "soulCampfire"],
