function mobWildLine(species, calmAt) {
  const one = species.displayName.toLowerCase();
  return `In the wild ${pluralOf2(species).toLowerCase()} are monsters: ${WILD_HOW[species.mobSource] ?? "they spawn in the dark (block light 0) and hunt you"}. To take one for the zoo: ${CALM_AS_IT_IS[species.mobSource] ?? `weaken it to ${Math.round(calmAt * 100) === 25 ? "a quarter" : `${Math.round(calmAt * 100)}%`} of its health or less, then`} use a Passivity Serum on it (Mob Taming research). It sparkles green, stands dazed a moment and is calm from then on: it never attacks, never burns in the sun and never despawns. A calmed ${one} follows someone holding ${BAIT[species.baitItem] ?? "its food"}; a Mob Cage carries it to its pen`;
}
function mobJournalLines(sp, balance, prof = { baseArea: 25, extraArea: 10, minHeight: 3 }) {
  const side = Math.round(Math.sqrt(prof.baseArea));
  const room = prof.aquatic ? `a pool in it: at least ${prof.baseArea} blocks of water for the first (${prof.extraArea} more for each more), ${prof.minDeepWater === prof.baseArea ? "all of them" : `${prof.minDeepWater} of them`} 2 deep or more, and a bank beside the water inside to use the Habitat Marker on, ${prof.minHeight} blocks of headroom over it` : `At least ${side} x ${side} of floor for the first (${prof.extraArea} more blocks for each more), ${prof.minHeight} blocks of headroom`;
  const out2 = [`§7The pen: ${PEN_HOW}${prof.aquatic ? `, with ${room}` : `. ${room}`}. Guests pay the Mob House's entry price to go into its hall once they can see a mob in a pen from a Viewing Point standing in the hall (a guest path through the hall's door to it). No wild monster spawns in the hall or the pens`];
  const likes = [];
  if (sp.mobFloor) likes.push(`${sp.mobFloor.how} under ${Math.round(sp.mobFloor.share * 100)}% of the floor${sp.mobFloor.underWater ? " (the bottom of the water and the bank)" : ""} or more`);
  if (sp.mobDecor) likes.push(`${sp.mobDecor.min} or more ${sp.mobDecor.how} in the pen${sp.mobDecor.where ? ` (${sp.mobDecor.where})` : ""}`);
  let line = likes.length ? `§7${sp.mobFloor ? "The floor" : "The pen"}: ${likes.join(", and ")}. Without ${sp.mobFloor && !sp.mobDecor ? "it" : "them"} comfort can't rise above ${balance.mobs.floorComfortCap}` : "";
  if (sp.lowLight) line += `${line ? ". And the dark" : "§7The dark"}: no daylight in the pen and nothing brighter than light ${darkLimit(sp, balance)}${sp.darkLight !== void 0 ? ` on the floor (a Nocturnal Lamp hung 3 blocks above the floor gives ${balance.nocturnal.maxLight - 3} right under it, and lets the guests see them)` : " (Nocturnal Lamps for the guests to see them by)"}; tinted glass to the hall keeps the daylight out (it comes in through the hall's door, even shut, and on through plain glass and iron bars); in light comfort can't rise above ${balance.chorusMoth.dimComfortCap}`;
  if (line) out2.push(line);
  out2.push(`§7In the pen: ${PEN_LIFE[sp.id] ?? MOUNT_PEN_LIFE[sp.id] ?? "they wander about"}. They never attack, never burn in the sun and never despawn, and nothing hurts them but a player's hits. Food: ${FOOD[sp.baitItem] ?? "their food"} in ${sp.aquariumFeeder ? "an Aquarium Feeder over the water" : "a Basic Feeder"}; a Hanging Food Basket gives them something to forage. ${MATES[sp.id] ?? `${pluralOf2(sp)} keep a pen to themselves`}`);
  if (MOB_LOOKS[sp.wildSource]?.sizes) out2.push(`§7Size: each keeps the size it had in the wild (small, medium or large) once calmed and caught; in the zoo it never grows or splits`);
  if (MOB_LOOKS[sp.wildSource]?.sheared) out2.push("§7Looks: a bogged sheared of its mushrooms in the wild stays bare once calmed and caught; the rest keep their mushrooms");
  const gear = MOB_LOOKS[sp.wildSource]?.gear;
  if (gear) out2.push(`§7Looks: each keeps the weapon it held in the wild (${listWords(sp.coats.map((c2) => `a ${c2.toLowerCase()}`), "or")})${MOB_LOOKS[sp.wildSource].gold ? " and any golden armour it wore" : ""}, calmed and caught; in the zoo it never uses it`);
  if (MOB_LOOKS[sp.wildSource]?.captain) out2.push("§7Looks: a captain (a patrol's or a raid's leader) keeps its ominous banner, calmed and caught; in the zoo it never leads anyone");
  if (sp.markNames) out2.push(`§7Looks: each keeps the job it had as a villager (its clothes show which of the ${sp.coats.length}) and the clothes of where it came from (${sp.markNames.join(", ")}). Calmed and caught, it keeps both`);
  return out2;
}
function mobHouseShare(price, balance) {
  const g4 = balance.mobHouse;
  const share = price <= g4.fair ? g4.shareAtFair + (g4.fair - price) * g4.sharePerCoinUnder : g4.shareAtFair - (price - g4.fair) * g4.sharePerCoinOver;
  return Math.max(0, Math.min(g4.shareMax, share));
}
function mobHouseSales({ guests, price, carry = 0, pens }, balance) {
  if (pens <= 0 || guests <= 0) return { paid: 0, revenue: 0, carry: 0 };
  const g4 = balance.mobHouse;
  const variety = Math.min(1, g4.varietyBase + g4.varietyPerPen * pens);
  const expected = carry + guests * mobHouseShare(price, balance) * variety;
  const paid = Math.max(0, Math.floor(expected + 1e-9));
  return { paid, revenue: paid * price, carry: Math.max(0, expected - paid) };
}
