// packs/BP/scripts/transport/journal.js
var TRANSFERS = "transfers";
var NEXT = {
  Reserved: ["Packed", "Aborted", "Recovered"],
  Packed: ["ArrivalPending", "Recovered"],
  ArrivalPending: ["Exhibited", "Released", "Packed", "Recovered"],
  Exhibited: [],
  Released: [],
  Aborted: [],
  Recovered: []
};
function canMove2(from, to) {
  return NEXT[from]?.includes(to) ?? false;
}
function move(store2, transfer, to, parkTime2, extra = {}) {
  if (!canMove2(transfer.phase, to)) throw new Error(`transfer ${transfer.id}: ${transfer.phase} -> ${to} is not allowed`);
  transfer.phase = to;
  transfer.updatedAt = parkTime2;
  Object.assign(transfer, extra);
  store2.put(TRANSFERS, transfer);
  return transfer;
}
function checkToken(store2, transferId, token) {
  const t2 = store2.get(TRANSFERS, transferId);
  if (!t2) return { ok: false, reason: "This carrier's record is missing." };
  if (t2.token !== token) return { ok: false, reason: "This carrier is a copy and holds no animal." };
  if (t2.phase !== "Packed") return { ok: false, reason: "This carrier has already been emptied." };
  return { ok: true, transfer: t2 };
}
function reconcile(store2, parkTime2) {
  const toHolding = [];
  for (const t2 of store2.all(TRANSFERS)) {
    if (t2.phase === "Reserved") {
      move(store2, t2, "Recovered", parkTime2, { note: "interrupted while packing" });
      toHolding.push(t2.animalId);
    } else if (t2.phase === "ArrivalPending") {
      move(store2, t2, "Packed", parkTime2, { note: "release interrupted; carrier still holds the animal" });
    }
  }
  return toHolding;
}
function pruneTransfers(store2, keep3 = 200) {
  const closed = store2.all(TRANSFERS).filter((t2) => !NEXT[t2.phase].length).sort((a, b) => a.updatedAt - b.updatedAt);
  for (const t2 of closed.slice(0, Math.max(0, closed.length - keep3))) store2.remove(TRANSFERS, t2.id);
}

