  if (sp.solitary) lines.splice(4, 0, `§c${wildLine2(BALANCE.tiger)}`);
  if (sp.basks) lines.splice(4, 0, `§c${wildLine4(BALANCE.croc)}`);
  if (sp.troop) lines.splice(4, 0, `§c${wildLine3(BALANCE.gorilla.bluff)}`);
  if (sp.roosts) lines.splice(4, 0, `§7${wildLine(BALANCE.owl)}`);
  if (sp.soulLight) lines.splice(4, 0, `§7${wildLine8(BALANCE.moth)}`);
  if (sp.substrate) lines.splice(4, 0, `§7${wildLine6(BALANCE.beetle)}`);
  if (sp.pads) lines.splice(4, 0, `§7${wildLine9(BALANCE.hopper)}`);
  if (sp.crevices) lines.splice(4, 0, `§7${wildLine10(BALANCE.snail)}`);
