  if (sp.chorusFlowers) lines.splice(4, 0, `§7${wildLine12(BALANCE.chorusMoth)}`);
  if (sp.warmPads) lines.splice(4, 0, `§7${wildLine13(BALANCE.starback)}`);
  if (sp.lushGround) lines.splice(4, 0, `§7${wildLine7(BALANCE.okapi)}`);
  if (sp.burrowSoil) lines.splice(4, 0, `§7${wildLine14(BALANCE.molebear)}`);
  if (sp.sculkFloor) lines.splice(4, 0, `§7${wildLine15(BALANCE.skulker)}`);
  if (sp.gladeFlowers) lines.splice(4, 0, `§7${wildLine16(BALANCE.unicorn)}`);
  if (sp.warmth) lines.splice(4, 0, `§7${wildLine17(BALANCE.dragon)}`);
  if (sp.hoard) lines.splice(4, 0, `§7${wildLine18(BALANCE.griffin)}`);
  if (sp.trunks) lines.splice(4, 0, `§7${wildLine19(BALANCE.glowhorn)}`);
  if (sp.snowFloor && sp.boss) lines.splice(4, 0, `§7${wildLine20()}`);
