  stats10.staffRooms = db.all("equipment").filter((e) => e.type === "staffroom" && e.valid).length;
  Object.assign(stats10, goalStats());
  const equipmentOf = (ex) => [...ex.fixtureIds ?? [], ...ex.feederIds ?? []].map((id) => db.get("equipment", id)).filter(Boolean);
  stats10.enriched = enrichedCount(exhibits, occupiedIds(exhibits, animals), equipmentOf, BALANCE.enrichment.fromEquipment);
