function* setUp(player, plan2, d, friends) {
  const st = plan2.street;
  const say18 = (text) => player.isValid && message(player, text);
  say18("§6Test setup: §fthe zoo is open. Moving the residents in...");
  yield* waitTicks(3);
  for (const s4 of st.signs) {
    try {
      const sign = d.getBlock(s4.pos)?.getComponent("minecraft:sign");
      sign?.setText(s4.text);
      sign?.setWaxed(true);
    } catch (error) {
      log(`test setup: the sign at ${s4.pos.x} ${s4.pos.y} ${s4.pos.z}: ${error}`);
    }
  }
  for (const h2 of st.homes) {
    h2.id = posKey(d.id, h2.mailbox);
    try {
      const b = d.getBlock(h2.mailbox);
      if (!b) continue;
      b.setPermutation(BlockPermutation18.resolve(BLOCKS.residentMailbox, h2.mailboxStates));
      homePlaced(player, b, true);
      setHomeAvailable(h2.id, false);
    } catch (error) {
      log(`test setup: ${h2.res}'s mailbox: ${error}`);
    }
  }
  for (const s4 of st.sites) {
    s4.id = posKey(d.id, s4.anchor);
    const b = d.getBlock(s4.anchor);
    if (b?.typeId === BLOCKS.workAnchor) anchorPlaced(player, b, true);
  }
  const homeOk = (h2) => {
    const rec4 = getHome(h2.id);
    return Boolean(rec4?.door && homeWorks(rec4) && homeWay(h2.id));
  };
  for (let t2 = 0; t2 < WAIT_SECONDS && !st.homes.every(homeOk); t2++) {
    if (t2 % 5 === 4) {
      for (const h2 of st.homes) if (!homeOk(h2)) queueHomeCheck(h2.id);
    }
    yield* waitTicks(20);
  }
  const moved = [];
  const problems = [];
  for (const h2 of st.homes) {
    const res2 = residentById(h2.res);
    const rec4 = getHome(h2.id);
    if (res2.unlock.kind === "quest" && !isUnlocked(h2.res)) problems.push(`§7${res2.name}'s house stands empty: a story brings them, not the test setup.`);
    else if (getResident(h2.res)) problems.push(`§e${res2.name} already lives somewhere in this world, so their house on the street is empty.`);
    else if (homeOk(h2) && moveIn(rec4, h2.res)) moved.push(h2.res);
    else problems.push(`§e${res2.name}'s house at ${h2.mailbox.x} ${h2.mailbox.y} ${h2.mailbox.z}: ${rec4 ? HOME_TEXT[rec4.problem] ?? "it isn't ready yet: use its mailbox to see why." : "its mailbox is missing."}`);
    if (rec4) setHomeAvailable(h2.id, true);
  }
  for (const s4 of st.sites) if (moved.includes(s4.worker)) assignWorker(s4.id, s4.worker);
  if (friends) for (const id of moved) setPoints(id, player, BALANCE.residents.bonds.tiers[2]);
  const siteOk = (s4) => {
    const rec4 = getSite(s4.id);
    return Boolean(rec4 && rec4.worker === s4.worker && !rec4.problem);
  };
  const working6 = st.sites.filter((s4) => moved.includes(s4.worker));
  for (let t2 = 0; t2 < WAIT_SECONDS && !working6.every(siteOk); t2++) {
    if (t2 % 10 === 9) {
      for (const s4 of working6) if (!siteOk(s4)) recheckSite(s4.id);
    }
    yield* waitTicks(20);
  }
  for (const s4 of working6) {
    if (siteOk(s4)) continue;
    const who = residentById(s4.worker)?.name;
    problems.push(`§e${who}'s ${s4.kind} at ${s4.anchor.x} ${s4.anchor.y} ${s4.anchor.z}: ${siteText(getSite(s4.id)?.problem ?? "noWorker", { who, minCells: BALANCE.residents.work.minCells })}`);
  }
  const sites = working6.filter(siteOk).length;
  const wood = working6.find((s4) => s4.kind === "woodlot" && siteOk(s4));
  const tracked = () => new Set((getSite(wood.id)?.saplings ?? []).map((p) => posKey(d.id, p)));
  const ready = () => (getSite(wood.id)?.work?.trees ?? 0) >= st.trees.length && st.spots.every((x) => tracked().has(posKey(d.id, x.pos)));
  let trees = 0;
  if (wood && st.spots.length) {
    for (let t2 = 0; t2 < WAIT_SECONDS / 2 && !ready(); t2++) {
      if (t2 % 5 === 0) {
        const have = tracked();
        for (const x of st.spots) if (!have.has(posKey(d.id, x.pos))) siteBlockPlaced(d.id, x.pos, x.sapling);
        recheckSite(wood.id);
      }
      yield* waitTicks(20);
    }
    const w = getSite(wood.id)?.work;
    trees = (w?.trees ?? 0) - (w?.big ?? 0);
    if (!ready()) problems.push(`§ePaola's woodlot: ${w?.trees ?? 0} of its ${st.trees.length} trees are ready to cut; use its Work Anchor to see why.`);
  }
  info(`test setup: ${moved.length} of ${st.homes.length} residents moved in; work sites: ${st.sites.map((s4) => `${s4.kind} ${getSite(s4.id)?.problem ?? "works"}`).join(", ")}; the woodlot: ${trees} trees an Apprentice can cut (${st.trees.length} grown by the setup)${friends ? "; friends" : ""}`);
  return { moved, problems, friends, sites, trees };
}

